#include <BleKeyboard.h>
#include <ESP32BLEKeyboardClient.h>

// Имя устройства, которое появится в поиске Bluetooth на ПК
BleKeyboard bleKeyboard("DIY Stream Deck", "ESP32", 100);

// Пины, к которым подключены 6 свитчей
const int buttonPins[6] = {13, 14, 27, 26, 25, 33};
bool lastButtonState[6] = {HIGH, HIGH, HIGH, HIGH, HIGH, HIGH};

void setup() {
  bleKeyboard.begin();
  for (int i = 0; i < 6; i++) {
    pinMode(buttonPins[i], INPUT_PULLUP); // Включаем внутренний резистор
  }
}

void loop() {
  if (bleKeyboard.isConnected()) {
    for (int i = 0; i < 6; i++) {
      bool currentState = digitalRead(buttonPins[i]);

      // Срабатывание в момент нажатия (переход из HIGH в LOW)
      if (lastButtonState[i] == HIGH && currentState == LOW) {
        triggerShortcut(i);
        delay(200); // Простая защита от дребезга контактов
      }
      lastButtonState[i] = currentState;
    }
  }
}

void triggerShortcut(int btnIndex) {
  bleKeyboard.press(KEY_LEFT_CTRL);
  bleKeyboard.press(KEY_LEFT_ALT);

  // Назначаем клавиши F1–F6 для каждой из 6 кнопок
  switch (btnIndex) {
    case 0: bleKeyboard.press(KEY_F1); break;
    case 1: bleKeyboard.press(KEY_F2); break;
    case 2: bleKeyboard.press(KEY_F3); break;
    case 3: bleKeyboard.press(KEY_F4); break;
    case 4: bleKeyboard.press(KEY_F5); break;
    case 5: bleKeyboard.press(KEY_F6); break;
  }

  delay(50);
  bleKeyboard.releaseAll(); // Отпускаем все зажатые клавиши
}
